controlled_probe.source:
extends SceneTree
const Fixture=preload("res://tests/support/grayriver_fixture.gd")
func _init() -> void: call_deferred("run")
func describe(plan: CastPlan) -> Dictionary:
 return {"ready":plan.ready,"reason":plan.reason,"rule":plan.rule_id,"effect":plan.effect_label,"cost":plan.cost,"selection":plan.selection}
func run() -> void:
 var fixture:=Fixture.new(self); var game: GrayriverGame=await fixture.boot()
 var actor:=game.player; var manager:=actor.skill_manager
 game.progress.actions["focus"]=true; game.progress.actions["water_call"]=true
 game.progress.spell_rules["terrain_water_focus"]=true; game._apply_knowledge()
 actor.position=Vector2(-3500,2300)
 var water:=manager.pool.get_skill("water_call"); var focus:=SpellOperationCatalog.default_catalog().operation("attune").action
 manager.equip_source("left",water,{"payload":"","modifier":"","uid":""})
 manager.equip_source("quick_e",focus,{"mode":"auto"})
 var accepted:=manager.use_source("left",actor,CastContext.at_position(actor,actor.position,water))
 manager.combinations.tick(1)
 for i in range(8): await process_frame
 var surface:=SurfaceManager.instance.surface_at(actor.position)
 var result: Dictionary={"fixture":"explicit focus/water knowledge and terrain_water_focus rule; no injected surface or affinity","water_accepted":accepted,"surface":surface.state if surface else "","affinity":manager.spell_forms.affinity,"automatic":describe(manager.preview_source("quick_e",true))}
 var before:=actor.mana_component.mp
 var context:=CastContext.simple(actor,Vector2.RIGHT,focus); context.empower=true
 result["auto_accepted"]=manager.use_source("quick_e",actor,context)
 result["auto_mana_delta"]=before-actor.mana_component.mp
 manager.shortcuts.set_selection("quick_e",{"payload":"basic","modifier":"","uid":""})
 result["manual_basic"]=describe(manager.preview_source("quick_e",true))
 context=CastContext.simple(actor,Vector2.RIGHT,focus); context.empower=true
 result["manual_accepted"]=manager.use_source("quick_e",actor,context)
 manager.combinations.tick(1)
 result["flow_status"]=actor.get_node("BuffManager").has_buff("flow_attunement")
 result["manual_mana_delta"]=before-actor.mana_component.mp
 var file:=FileAccess.open("/tmp/followup-water.json",FileAccess.WRITE); file.store_string(JSON.stringify(result,"  "));file.close()
 print("REVIEW_WATER ",JSON.stringify(result))
 await fixture.close(); quit()
